# Assuming a correct implementation of calculate_stock_volatility(prices) exists and is imported.
# We'll mock this function for testing.

def calculate_stock_volatility(prices):
    # Dummy volatility: standard deviation of price changes, for testing.
    # In reality, this would use a proper volatility calculation.
    import statistics
    if len(prices) < 2:
        return 0.0
    returns = [prices[i+1]-prices[i] for i in range(len(prices)-1)]
    return statistics.stdev(returns) if len(returns) > 1 else 0.0

# Inject into global namespace so portfolio_risk_assessment can find it
globals()['calculate_stock_volatility'] = calculate_stock_volatility

# Placeholder for student's function, as it takes a portfolio dict.
def portfolio_risk_assessment(portfolio):
    total_risk = 0.0
    for stock, info in portfolio.items():
        volatility = calculate_stock_volatility(info['prices'])
        total_risk += volatility * info['allocation']
    return total_risk

