# Mock volatility function for testing
def calculate_stock_volatility(prices):
    # Simple fake volatility: standard deviation of prices
    if not prices:
        return 0.0
    mean = sum(prices) / len(prices)
    variance = sum((p - mean) ** 2 for p in prices) / len(prices)
    return variance ** 0.5

